c.python:
class Solution:
    def nthPersonGetsNthSeat(self, n: int) -> float:
        dp = [0.0] * (n + 1)
        dp[1] = 1.0
        for i in range(2, n + 1):
            dp[i] = (1.0 + (i - 2) * dp[i - 1]) / i
        return dp[n]

