class Solution {
public:
    double nthPersonGetsNthSeat(int n) {
        vector<double> dp(n + 1);
        dp[1] = 1.0;
        for (int i = 2; i <= n; ++i)
            dp[i] = (1.0 + (double)(i - 2) * dp[i - 1]) / i;
        return dp[n];
    }
};

